/// <summary>
/// Return Order Disposition Code Update UIBuilder
/// </summary>
public class METReturnOrderDispositionCodeUpdUIBuilder extends SysOperationAutomaticUIBuilder
{
    private METReturnOrderDispositionCodeUpdContract contract;
    private DialogField                   dispositionCodeDialogField;


}

Method.Source:
/// <summary>
/// Overrides the method to add custom logic.
/// </summary>
public void postBuild()
{
    super();

    contract = this.dataContractObject() as METReturnOrderDispositionCodeUpdContract;

    dispositionCodeDialogField = this.bindInfo().getDialogField(contract, methodStr(METReturnOrderDispositionCodeUpdContract, parmDispositionCode));

    dispositionCodeDialogField.fieldControl().mandatory(true);
}

/// <summary>
///  Constructs lookup againt order type.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
private void lookupOrderType(FormStringControl _control)
{
    Query                query;
    QueryBuildDataSource qbds;
    SysTableLookup       sysTableLookup;

    query = new Query();
    qbds  = query.addDataSource(tableNum(METSalesOrderTypes));

    qbds.addRange(fieldNum(METSalesOrderTypes, IncSpecialOrders)).value(enum2Str(NoYes::Yes));

    sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesOrderTypes), _control);

    sysTableLookup.addLookupField(fieldNum(METSalesOrderTypes,SalesOrderTypeID), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
